export function getVocabByLevel(level) {
  return vocabularyData.filter(v => v.level === level);
}

export function getVocabByTheme(theme) {
  return vocabularyData.filter(v => v.theme === theme);
}

export function searchVocab(query) {
  const q = query.toLowerCase().trim();
  if (!q) return [];
  return vocabularyData.filter(v =>
    v.es.toLowerCase().includes(q) ||
    v.fr.toLowerCase().includes(q)
  );
}
